const {chromium}=require('playwright'),{pathToFileURL}=require('url'),path=require('path');
(async()=>{const b=await chromium.launch({args:['--no-sandbox']});try{const p=await b.newPage({viewport:{width:390,height:900},timezoneId:'Europe/Kyiv'}),errors=[];p.on('pageerror',e=>errors.push(e.message));await p.clock.install({time:new Date('2026-10-22T09:00:00Z')});await p.goto(process.env.ART_SITE_URL||pathToFileURL(path.resolve('index.html')).href);await p.evaluate(()=>{window.speak=()=>Promise.resolve();window.tone=()=>{}});await p.click('#learningTab');await p.evaluate(()=>{const a=DEUTSCH_ADAPTIVE;profileStorage.removeItem(a.key);if(a.plan().selected.map(c=>c.de).join(',')!=='ich,du,er,sie,wir')throw Error('Five initial pronouns missing');a.start();const item=a.snapshot().queue[0];if(!document.querySelector('.al-word img'))throw Error('No lesson-style artwork');document.querySelector('#alContinue').click();a.answer(item.c.de)});await p.clock.runFor(2100);if(await p.evaluate(()=>DEUTSCH_ADAPTIVE.snapshot().index)!==1)throw Error('Correct answer did not auto-advance');
await p.evaluate(()=>{const a=DEUTSCH_ADAPTIVE,s=a.snapshot();if(s.queue[s.index].intro)document.querySelector('#alContinue').click();a.answer('wrong')});const at=await p.evaluate(()=>DEUTSCH_ADAPTIVE.snapshot().index);await p.clock.runFor(10000);if(await p.evaluate(()=>DEUTSCH_ADAPTIVE.snapshot().index)!==at||!await p.locator('#alFeedback.bad').isVisible())throw Error('Wrong answer auto-advanced or no signal');await p.click('#alNext');
await p.evaluate(()=>{const a=DEUTSCH_ADAPTIVE;profileStorage.removeItem(a.key);a.start();while(a.snapshot()?.queue[a.snapshot().index]){const item=a.snapshot().queue[a.snapshot().index];if(item.intro)document.querySelector('#alContinue').click();a.answer(item.c.de);document.querySelector('#alNext').click()}if(a.plan().newToday!==5||a.plan().n!==1||!a.plan().selected.length)throw Error('Five-item goal blocks continued learning');document.querySelector('#alMore').click();while(a.snapshot()?.queue[a.snapshot().index]){const item=a.snapshot().queue[a.snapshot().index];if(item.intro)document.querySelector('#alContinue').click();a.answer(item.c.de);document.querySelector('#alNext').click()}if(a.plan().newToday!==7)throw Error('Cannot continue beyond daily guide');setMode('home');if(a.snapshot())throw Error('Navigation did not cancel session');setMode('learning');});await p.clock.runFor(5000);
await p.reload();await p.click('#learningTab');if(await p.evaluate(()=>DEUTSCH_ADAPTIVE.plan().newToday)!==7)throw Error('Persistence lost');await p.evaluate(()=>{for(const s of DEUTSCH_ADAPTIVE.stages)for(const c of s.cards){if(!RECORDED_AUDIO[c.de.toLowerCase().replace(/[.!?,]/g,'')])throw Error('Missing recording '+c.de);if(!DEUTSCH_ADAPTIVE.art(c))throw Error('Missing artwork '+c.de)}});
for(const width of [320,390,768,1280]){await p.setViewportSize({width,height:900});if(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth+1))throw Error('Overflow '+width)}await p.click('#profileButton');await p.fill('#profileAddInput','Adaptive child');await Promise.all([p.waitForEvent('load'),p.click('#profileAddForm button')]);await p.click('#learningTab');if(!await p.evaluate(()=>Object.keys(DEUTSCH_ADAPTIVE.plan().d.cards).length===0))throw Error('Profile data leaked');if(errors.length)throw Error(errors.join(';'));console.log('PASS five pronouns, lesson artwork/audio, soft daily goal, unlimited continuation, auto-next on success, held errors, navigation cancellation, persistence and profiles');}finally{await b.close()}})().catch(e=>{console.error(e);process.exit(1)});
